"""Controller regressions with generated bytes only; no JVM or real dataset."""
from __future__ import annotations

import argparse
import contextlib
import importlib.util
import io
import json
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch


class StudyControllerTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="lm1-controller-test-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.relative = "experimental/lm1-training-recovery-20261104/suffix-study"
        self.experiment = self.root / self.relative
        self.experiment.mkdir(parents=True)
        script = self.experiment / "run_registered_study.py"
        script.write_bytes(Path(__file__).with_name("run_registered_study.py").read_bytes())
        spec = importlib.util.spec_from_file_location("synthetic_study_controller", script)
        self.module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(self.module)
        self.inputs = self.root / "inputs"
        self.inputs.mkdir()
        for name in ("lm1-baseline.lm1", "lm1-tokenizer.lmbp", "train.txt"):
            (self.inputs / name).write_bytes(("synthetic " + name).encode())
        self.jar = self.root / "study.jar"
        self.stdlib = self.root / "stdlib.jar"
        self.jar.write_bytes(b"synthetic executable")
        self.stdlib.write_bytes(b"synthetic standard library")
        self.source = self.root / "registered.kt"
        self.source.write_bytes(b"synthetic source")
        self.test_data = self.root / "experimental/lm1-training-recovery-20261104/intent-data/test.sealed.tsv"
        self.test_data.parent.mkdir()
        self.test_data.write_bytes(b"synthetic registered bytes, not a real test dataset")
        registered = [script, self.source, self.test_data]
        self.registration = {
            "files": {str(p.relative_to(self.root)): self.module.sha(p) for p in registered},
            "inputs": {p.name: self.module.sha(p) for p in self.inputs.iterdir()},
            "jarSha256": self.module.sha(self.jar), "stdlibSha256": self.module.sha(self.stdlib),
        }
        (self.experiment / "registration.json").write_text(json.dumps(self.registration))
        args = argparse.Namespace(output=self.root / "results", jar=self.jar, stdlib=self.stdlib,
                                  inputs=self.inputs, source_commit="a" * 40)
        self.study = self.module.Study(args)
        self.training_evidence("small", (4, 8, 12, 16))
        self.training_evidence("wide", (4, 12, 16, 20))
        with contextlib.redirect_stdout(io.StringIO()):
            self.study.freeze()
        self.frozen = self.study.out / "selection-freeze.json"
        self.frozen_bytes = self.frozen.read_bytes()

    @staticmethod
    def row(kind, **values):
        return "\t".join([kind, *(f"{key}={value}" for key, value in values.items())]) + "\n"

    def training_evidence(self, variant, correct):
        directory = self.study.out / ("intent-" + variant)
        checkpoints = directory / "checkpoints"
        checkpoints.mkdir(parents=True, exist_ok=True)
        records = []
        hashes = {}
        for step, successes, nll in zip((0, 128, 256, 512), correct, (4.0, 3.0, 2.0, 1.0)):
            raw = f"synthetic {variant} checkpoint {step}".encode()
            temporary = directory / "checkpoint.tmp"
            temporary.write_bytes(raw)
            value = self.module.sha(temporary)
            checkpoint = checkpoints / (value + ".lm1")
            checkpoint.write_bytes(raw)
            temporary.unlink()
            hashes[step] = value
            records.append(self.row("CHECKPOINT", step=step, sha256=value, path=checkpoint))
            records.append(self.row("SCORE", split="dev", step=step, correct=successes,
                                    total=24, answerNll=nll))
        capacity = directory / "capacity-before.tsv"
        capacity.write_text(self.row("CAPACITY_RESULT", **{"pass": "true", "checkpointSha256": hashes[0],
                                                          "measuredRepeats": 3, "firstTokenObservations": 3,
                                                          "full32TokenObservations": 3}))
        records.append(self.row("INITIAL_CAPACITY_GATE", **{"pass": "true", "checkpointSha256": hashes[0],
                                                             "logSha256": self.module.sha(capacity)}))
        records.append(self.row("MANIFEST", variant=variant, tokenScheduleSha256="b" * 64))
        records.append(self.row("SELECTION", checkpointSha256=hashes[512], step=512,
                                devCorrect=correct[-1], devTotal=24, devAnswerNll=1.0,
                                testRead="false", inputsUnchanged="true"))
        log = self.study.logs / ("intent-" + variant + ".tsv")
        log.write_text("".join(records))
        receipt = {"label": "intent-" + variant, "returncode": 0, "timeout": False,
                   "registeredBytesUnchanged": True, "logSha256": self.module.sha(log),
                   "registrationSha256": self.study.registration_sha,
                   "sourceCommit": self.study.args.source_commit, "jarSha256": self.registration["jarSha256"]}
        (self.study.logs / ("intent-" + variant + ".receipt.json")).write_text(json.dumps(receipt))

    def assert_test_rejected(self, exceptions=(RuntimeError, ValueError, OSError), message=None):
        with patch.object(self.study, "run") as run:
            if message:
                with self.assertRaisesRegex(exceptions, message):
                    self.study.test()
            else:
                with self.assertRaises(exceptions):
                    self.study.test()
            run.assert_not_called()
        self.assertFalse((self.study.out / "intent-summary.json").exists())

    def test_foreign_initial_control_is_rejected_before_any_test(self):
        foreign = self.root / "foreign.lm1"
        foreign.write_bytes(b"synthetic foreign checkpoint with a valid matching hash")
        for arm in ("S0", "W0"):
            with self.subTest(arm=arm):
                freeze = json.loads(self.frozen_bytes)
                freeze["arms"][arm].update(path=str(foreign), checkpointSha256=self.module.sha(foreign))
                self.frozen.write_text(json.dumps(freeze))
                self.assert_test_rejected(message="INVALID_TEST_AUTHORIZATION")

    def test_changed_freeze_hash_schedule_or_source_is_rejected(self):
        for field, replacement in (("testSha256", "0" * 64), ("tokenScheduleSha256", "0" * 64),
                                   ("sourceCommit", "0" * 40)):
            with self.subTest(field=field):
                freeze = json.loads(self.frozen_bytes)
                freeze[field] = replacement
                self.frozen.write_text(json.dumps(freeze))
                self.assert_test_rejected(message="INVALID_TEST_AUTHORIZATION")

    def test_existing_freeze_does_not_bypass_lost_development_signal(self):
        self.training_evidence("wide", (4, 5, 6, 7))
        self.assert_test_rejected(message="NO_DEVELOPMENT_SIGNAL")
        self.assertEqual(self.frozen_bytes, self.frozen.read_bytes())

    def test_missing_or_invalid_freeze_is_rejected_before_any_test(self):
        for contents in (None, b"{", b"{}"):
            with self.subTest(contents=contents):
                if contents is None:
                    self.frozen.unlink()
                else:
                    self.frozen.write_bytes(contents)
                self.assert_test_rejected()

    def fake_test_run(self, label, main, arguments, **options):
        self.assertEqual("LmIntentSuffixStudy", main)
        self.assertEqual("test", arguments[0])
        self.assertFalse(options.get("capacity", False))
        arm = label.removeprefix("test-")
        correct = {"S0": 4, "W0": 4, "S1": 32, "W1": 40}[arm]
        text = self.row("TEST_INPUT", checkpointSha256=self.module.sha(Path(arguments[1])),
                        testSha256=self.module.sha(self.test_data))
        text += self.row("SCORE", split="test", step=512 if arm.endswith("1") else 0,
                         correct=correct, total=48, classCorrect=",".join([str(correct // 4)] * 4),
                         classTotal="12,12,12,12", answerNll=0.2, eosNll=0.1,
                         prematureEos=0, missingEos=0, generatedTokens=48)
        (self.study.logs / (label + ".tsv")).write_text(text)
        return subprocess.CompletedProcess([main, *arguments], 0)

    def test_valid_freeze_allows_exactly_four_mock_test_runs(self):
        with patch.object(self.study, "run", side_effect=self.fake_test_run) as run, \
                patch.object(self.module.subprocess, "Popen", side_effect=AssertionError("JVM is forbidden")), \
                contextlib.redirect_stdout(io.StringIO()):
            self.study.test()
        self.assertEqual(["test-S0", "test-W0", "test-S1", "test-W1"], [call.args[0] for call in run.call_args_list])
        summary = json.loads((self.study.out / "intent-summary.json").read_text())
        self.assertIs(True, summary["limitedBenchmarkLearningCriterionPassed"])
        self.assertIs(False, summary["modelPromotion"])
        self.assertEqual(self.module.sha(self.frozen), summary["selectionSha256"])

    def test_changed_registered_bytes_block_test_before_run(self):
        for path in (self.source, self.test_data, self.jar, self.stdlib,
                     self.inputs / "lm1-baseline.lm1", self.experiment / "registration.json"):
            with self.subTest(file=path.name):
                original = path.read_bytes()
                try:
                    path.write_bytes(original + b" changed")
                    self.assert_test_rejected(RuntimeError)
                finally:
                    path.write_bytes(original)

    def test_actual_test_input_identity_must_match_freeze(self):
        for field in ("checkpointSha256", "testSha256"):
            with self.subTest(field=field):
                def wrong_identity(label, main, arguments, **options):
                    result = self.fake_test_run(label, main, arguments, **options)
                    path = self.study.logs / (label + ".tsv")
                    lines = path.read_text().splitlines()
                    parts = lines[0].split("\t")
                    lines[0] = "\t".join(field + "=" + "0" * 64 if item.startswith(field + "=") else item for item in parts)
                    path.write_text("\n".join(lines) + "\n")
                    return result
                with patch.object(self.study, "run", side_effect=wrong_identity) as run:
                    with self.assertRaises(RuntimeError):
                        self.study.test()
                self.assertEqual(1, run.call_count, "invalid first-arm evidence must stop all remaining tests")
                self.assertFalse((self.study.out / "intent-summary.json").exists())


if __name__ == "__main__":
    unittest.main()
